       "AVATAR",                                                                                                                                                                                                                                                                                    
       "STATE_CODE",                                                                                                                                                                                                                                                                                
       "MOBILE",                                                                                                                                                                                                                                                                                    
       "JOB_NUMBER",                                                                                                                                                                                                                                                                                
       "EMAIL",                                                                                                                                                                                                                                                                                     
       "HIRED_DATE",                                                                                                                                                                                                                                                                                
       "MANAGER_USER_ID",                                                                                                                                                                                                                                                                           
